def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    row_groups = []
    start = 0
    for r in range(h):
        if r in sep_rows:
            if start < r:
                row_groups.append((start, r))
            start = r + 1
    if start < h:
        row_groups.append((start, h))

    col_groups = []
    start = 0
    for c in range(w):
        if c in sep_cols:
            if start < c:
                col_groups.append((start, c))
            start = c + 1
    if start < w:
        col_groups.append((start, w))

    from collections import Counter
    colors = Counter(
        grid[r][c]
        for r0, r1 in row_groups
        for c0, c1 in col_groups
        for r in range(r0, r1)
        for c in range(c0, c1)
    )
    background = colors.most_common(1)[0][0]

    output = [[background for _ in col_groups] for _ in row_groups]
    for i, (r0, r1) in enumerate(row_groups):
        for j, (c0, c1) in enumerate(col_groups):
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if count >= 2:
                output[i][j] = 1

    return output
